// ── Validate payload ─────────────────────────────────────────────
// Mode: Run Once for All Items. Input: the Webhook item.
// Output: one item { valid, errors[], claim (normalised), received_at }
const body = $input.first().json.body;
const errors = [];

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (typeof v === 'string' ? v.trim() : '');

if (!isObj(body)) {
  return [{ json: { valid: false, errors: ['Body must be a JSON object'], claim: null } }];
}

const claimant = isObj(body.claimant) ? body.claimant : {};
if (!isObj(body.claimant)) errors.push('claimant is required and must be an object');

const claim = {
  idempotency_key: str(body.idempotency_key),
  policy_number:   str(body.policy_number).toUpperCase(),
  channel:         str(body.channel).toLowerCase() || 'api',
  claimant_name:   str(claimant.name),
  claimant_email:  str(claimant.email).toLowerCase(),
  claimant_phone:  str(claimant.phone) || null,
  incident_date:   str(body.incident_date),
  claimed_amount:  body.claimed_amount,
  currency:        (str(body.currency) || 'ZAR').toUpperCase(),
  description:     str(body.description),
};

// idempotency_key
if (!claim.idempotency_key) errors.push('idempotency_key is required');
else if (claim.idempotency_key.length < 8 || claim.idempotency_key.length > 100)
  errors.push('idempotency_key must be 8-100 characters');

// policy_number
if (!claim.policy_number) errors.push('policy_number is required');
else if (!/^POL-[A-Z]{3}-\d{6}$/.test(claim.policy_number))
  errors.push('policy_number must look like POL-XXX-123456');

// claimant
if (!claim.claimant_name) errors.push('claimant.name is required');
if (!claim.claimant_email) errors.push('claimant.email is required');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(claim.claimant_email))
  errors.push('claimant.email is not a valid email address');

// channel
const CHANNELS = ['web', 'whatsapp', 'email', 'call_centre', 'api'];
if (!CHANNELS.includes(claim.channel))
  errors.push(`channel must be one of: ${CHANNELS.join(', ')}`);

// incident_date: real calendar date, not in the future (SAST)
const today = $now.setZone('Africa/Johannesburg').toISODate();
if (!claim.incident_date) errors.push('incident_date is required');
else if (!/^\d{4}-\d{2}-\d{2}$/.test(claim.incident_date) || !DateTime.fromISO(claim.incident_date).isValid)
  errors.push('incident_date must be a real date in YYYY-MM-DD format');
else if (claim.incident_date > today)
  errors.push(`incident_date ${claim.incident_date} is in the future`);

// claimed_amount
if (claim.claimed_amount === undefined || claim.claimed_amount === null || claim.claimed_amount === '')
  errors.push('claimed_amount is required');
else if (typeof claim.claimed_amount !== 'number' || !Number.isFinite(claim.claimed_amount))
  errors.push('claimed_amount must be a number');
else if (claim.claimed_amount <= 0)
  errors.push('claimed_amount must be greater than 0');
else if (Number(claim.claimed_amount.toFixed(2)) !== claim.claimed_amount) // float-safe
  errors.push('claimed_amount can have at most 2 decimal places');

// currency
if (claim.currency !== 'ZAR') errors.push('currency must be ZAR');

// description
if (!claim.description) errors.push('description is required');
else if (claim.description.length < 10 || claim.description.length > 5000)
  errors.push('description must be 10-5000 characters');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    claim,
    raw_payload: body,
    received_at: $now.toISO(),
  },
}];

// ── Check eligibility ────────────────────────────────────────────
// Mode: Run Once for All Items.
// Input: one row from Load_Policy_PG (policy columns are null if not found).
// Output: one item carrying everything later nodes need.
const v = $('Validate_Payload_Func').first().json;  // validated claim from earlier
const p = $input.first().json;                      // policy row from Postgres
const c = v.claim;
const reasons = [];

if (!p.policy_number) {
  reasons.push('policy_not_found');
} else {
  if (p.status !== 'active') reasons.push('policy_not_active');
  // Dates are 'YYYY-MM-DD' strings, so plain string comparison is safe
  if (c.incident_date < p.start_date || c.incident_date > p.end_date)
    reasons.push('incident_outside_cover');
  if (c.claimed_amount > p.sum_insured) reasons.push('amount_exceeds_sum_insured');
}

return [{
  json: {
    eligible: reasons.length === 0,
    reasons,
    claim: c,
    policy: p.policy_number ? p : null,
    prior_claims_12m: p.prior_claims_12m ?? 0,
    raw_payload: v.raw_payload,
    received_at: v.received_at,
  },
}];

// ── Build AI prompt ──────────────────────────────────────────────
// Builds the user message every LLM branch (and the mock) receives.
// Data minimisation: no name, email, phone or policy number goes to the LLM.
const e = $input.first().json;          // item from Check_Eligibility_Func
const c = e.claim;
const p = e.policy;

// Untrusted text: stop the claimant closing our tag, and drop curly braces
// (LangChain prompt templates treat {braces} as variables).
const description = c.description
  .replace(/<\s*\/?\s*claim_description\s*>/gi, '[tag removed]')
  .replace(/[{}]/g, (m) => (m === '{' ? '(' : ')'));

const user_prompt = [
  'Analyse this insurance claim.',
  '',
  `Product: ${p.product}`,
  `Sum insured: R ${p.sum_insured}`,
  `Policy start date: ${p.start_date}`,
  `Incident date: ${c.incident_date}`,
  `Reported date: ${$now.setZone('Africa/Johannesburg').toISODate()}`,
  `Claimed amount: R ${c.claimed_amount}`,
  `Channel: ${c.channel}`,
  '',
  '<claim_description>',
  description,
  '</claim_description>',
].join('\n');

return [{ json: { ...e, ai_input: { user_prompt, description } } }];

// ── Mock AI analysis (LLM_MODE=mock) ─────────────────────────────
// Deterministic, keyword-based stand-in for the LLM so the pipeline and the
// test suite run without an API key. Returns the same shape as the real
// chains: { output: { ...analysis } }.
const e = $input.first().json;
const text = e.ai_input.description.toLowerCase();
const has = (...words) => words.some((w) => text.includes(w));

// Lets the tests prove the failure path: this node's error output goes to
// Normalise_AI_Func exactly like a real LLM failure would.
if (text.includes('[[simulate_llm_failure]]')) {
  throw new Error('Simulated LLM failure (mock mode)');
}

let a;
if (has('windscreen', 'windshield', 'glass')) {
  a = { claim_type: 'windscreen', severity: 'low', ai_risk_score: 10, missing_information: ['photo of damage'] };
} else if (has('burst pipe', 'geyser', 'water', 'leak')) {
  a = { claim_type: 'water_damage', severity: 'medium', ai_risk_score: 30, missing_information: ["plumber's report", 'photos of damage'] };
} else if (has('stolen', 'theft', 'hijack')) {
  a = { claim_type: 'theft', severity: 'high', ai_risk_score: 55, missing_information: ['police case number'] };
} else {
  a = { claim_type: 'other', severity: 'medium', ai_risk_score: 35, missing_information: ['photos of damage'] };
}

const fraud_indicators = [];
if (has('cash', 'urgent', 'asap', 'today')) {
  fraud_indicators.push('urgency_language', 'cash_payment_request');
  a.ai_risk_score += 25;
}
if (has('ignore previous', 'ignore all previous', 'system prompt', 'you are now', 'instructions')) {
  fraud_indicators.push('prompt_injection_attempt');
  a.ai_risk_score += 30;
}

return [{
  json: {
    output: {
      ...a,
      ai_risk_score: Math.min(a.ai_risk_score, 100),
      fraud_indicators,
      summary: `Mock analysis: ${a.claim_type.replace('_', ' ')} claim, ${a.severity} severity.`,
    },
  },
}];

// ── Normalise AI result ──────────────────────────────────────────
// Receives ONE item from whichever branch ran: a success ({ output }) or an
// error-output item ({ error }). Never trusts the model: every field is
// checked against the schema. Anything wrong -> ai.status = 'failed', which
// Chunk D routes to manual review.
const ctx = $('Check_Eligibility_Func').first().json;   // claim + policy context
const item = $input.first().json;

const mode = String($env.LLM_MODE || '').toLowerCase();
const model = { mock: 'mock', openai: $env.OPENAI_MODEL, anthropic: $env.ANTHROPIC_MODEL, ollama: $env.OLLAMA_MODEL }[mode] || `unknown mode "${mode}"`;

const CLAIM_TYPES = ['windscreen', 'collision', 'theft', 'water_damage', 'fire', 'storm', 'burglary',
  'accidental_damage', 'lost_baggage', 'medical', 'other'];
const SEVERITIES = ['low', 'medium', 'high', 'critical'];
const INDICATORS = ['new_policy_concern', 'vague_description', 'inconsistent_details', 'urgency_language',
  'cash_payment_request', 'amount_seems_inflated', 'third_party_pressure', 'prompt_injection_attempt', 'other'];

const problems = [];
const warnings = [];
const isStrArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
const norm = (s) => String(s).trim().toLowerCase().replace(/[\s-]+/g, '_');

let ai = null;
if (item.error) {
  const msg = typeof item.error === 'string' ? item.error : (item.error.message || JSON.stringify(item.error));
  problems.push(`llm_error: ${msg.slice(0, 300)}`);
} else if (!['mock', 'openai', 'anthropic', 'ollama'].includes(mode)) {
  problems.push(`unknown LLM_MODE "${mode}"`);
} else if (!item.output || typeof item.output !== 'object') {
  problems.push('no structured output from model');
} else {
  const o = item.output;
  const claim_type = norm(o.claim_type ?? '');
  const severity = norm(o.severity ?? '');
  const score = Number(o.ai_risk_score);

  if (!CLAIM_TYPES.includes(claim_type)) problems.push(`invalid claim_type "${o.claim_type}"`);
  if (!SEVERITIES.includes(severity)) problems.push(`invalid severity "${o.severity}"`);
  if (typeof o.ai_risk_score !== 'number' && typeof o.ai_risk_score !== 'string') problems.push('ai_risk_score missing');
  else if (!Number.isFinite(score)) problems.push(`ai_risk_score not a number "${o.ai_risk_score}"`);
  if (typeof o.summary !== 'string' || !o.summary.trim()) problems.push('summary missing');
  if (!isStrArray(o.fraud_indicators ?? [])) problems.push('fraud_indicators must be a list of strings');
  if (!isStrArray(o.missing_information ?? [])) problems.push('missing_information must be a list of strings');

  if (problems.length === 0) {
    // Known vocabulary only; anything unexpected is kept as "other" and noted.
    const indicators = [...new Set((o.fraud_indicators ?? []).map((x) => {
      const n = norm(x);
      if (INDICATORS.includes(n)) return n;
      warnings.push(`unknown indicator "${x}" stored as other`);
      return 'other';
    }))];
    const clamped = Math.max(0, Math.min(100, Math.round(score)));
    if (clamped !== score) warnings.push(`ai_risk_score ${score} clamped to ${clamped}`);

    ai = {
      claim_type,
      severity,
      summary: o.summary.trim().slice(0, 500),
      fraud_indicators: indicators,
      ai_risk_score: clamped,
      missing_information: (o.missing_information ?? []).map((s) => s.trim()).filter(Boolean).slice(0, 10),
    };
  }
}

return [{
  json: {
    ...ctx,
    ai: {
      status: ai ? 'ok' : 'failed',
      mode,
      model,
      problems,
      warnings,
      claim_type: ai?.claim_type ?? null,
      severity: ai?.severity ?? null,
      summary: ai?.summary ?? null,
      fraud_indicators: ai?.fraud_indicators ?? [],
      ai_risk_score: ai?.ai_risk_score ?? null,
      missing_information: ai?.missing_information ?? [],
    },
  },
}];
